import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.7R1OEGYz.js";const u=JSON.parse('{"title":"Upgrading","description":"","frontmatter":{},"headers":[],"relativePath":"upgrading.md","filePath":"upgrading.md","lastUpdated":1794056215000}'),n={name:"upgrading.md"};function r(o,e,l,h,d,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h1><h2 id="session-telemetry" tabindex="-1">Session telemetry <a class="header-anchor" href="#session-telemetry" aria-label="Permalink to &quot;Session telemetry&quot;">​</a></h2><p>After installing the server and runtime update for session telemetry authentication, restart existing Claude sessions so their usage continues to be recorded. New Claude sessions receive the telemetry environment automatically. This applies in both editions.</p><p>If you use a custom <code>telemetry.otlpEndpoint</code>, metrics go to that collector without a session callback credential and do not count in AgentHub. Leave the setting empty for AgentHub usage. See <a href="/docs/chart-values#telemetry-collectors">telemetry collectors</a>.</p><h2 id="the-reuse-values-trap" tabindex="-1">The <code>--reuse-values</code> trap <a class="header-anchor" href="#the-reuse-values-trap" aria-label="Permalink to &quot;The \`--reuse-values\` trap&quot;">​</a></h2><p><code>helm upgrade --reuse-values</code> reuses the values from the last release and merges your new <code>--set</code> flags on top. What it does <strong>not</strong> do is pick up defaults that were added to the chart since that release was installed.</p><p>So when a chart version introduces a new top-level key, an upgrade with <code>--reuse-values</code> leaves that key unset — and any template that reads it unguarded fails:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error: UPGRADE FAILED: template: open-agenthub/templates/signal-cli.yaml:1:14</span></span>
<span class="line"><span>  executing &quot;open-agenthub/templates/signal-cli.yaml&quot; at &lt;.Values.chat.signal.enabled&gt;:</span></span>
<span class="line"><span>    nil pointer evaluating interface {}.enabled</span></span></code></pre></div><p>The error names the template, not the cause, which makes it a genuinely confusing dead end. Nothing is wrong with your command; the values simply have a hole in them.</p><h3 id="the-fix" tabindex="-1">The fix <a class="header-anchor" href="#the-fix" aria-label="Permalink to &quot;The fix&quot;">​</a></h3><p>Use <code>--reset-then-reuse-values</code> (Helm 3.14 and newer). It resets to the chart defaults and then re-applies the values you supplied, so new keys arrive with their defaults:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub/open-agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reset-then-reuse-values</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat.telegram.enabled=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><h3 id="the-better-fix" tabindex="-1">The better fix <a class="header-anchor" href="#the-better-fix" aria-label="Permalink to &quot;The better fix&quot;">​</a></h3><p>Keep a values file per environment and pass it with <code>-f</code>. Then nothing is implicit:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Export what the release currently has, once</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> values</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yaml</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-values.yaml</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Edit it, then from here on</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub/open-agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-values.yaml</span></span></code></pre></div><p>That file holds secrets — database password, S3 keys, bot tokens — so keep it out of version control.</p><h2 id="image-versions-follow-the-chart" tabindex="-1">Image versions follow the chart <a class="header-anchor" href="#image-versions-follow-the-chart" aria-label="Permalink to &quot;Image versions follow the chart&quot;">​</a></h2><p>Since chart 1.19.0, <code>image.tag</code> is empty by default and means the chart&#39;s <code>appVersion</code>: chart X.Y.Z runs the images of release X.Y.Z, and upgrading the chart moves every component — backend, frontend, browser, renderer and all agent runtimes — to the new release. Check what a release runs with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub-backend</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jsonpath=&#39;{.spec.template.spec.containers[0].image}&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span></span></code></pre></div><p>Earlier charts defaulted to <code>latest</code> with <code>pullPolicy: IfNotPresent</code>. Such an install ran whatever image its nodes had pulled first, which could be newer than the chart, and an upgrade did not move it. After upgrading to 1.19.0 or later it runs the matching release images instead.</p><p>If you set <code>image.tag</code> yourself, nothing changes: an explicit value always wins. To keep following the newest build on purpose, set <code>image.tag: latest</code> together with <code>image.pullPolicy: Always</code> and <code>agent.pullPolicy: Always</code>.</p><h2 id="installs-without-oidc-the-api-key" tabindex="-1">Installs without OIDC: the API key <a class="header-anchor" href="#installs-without-oidc-the-api-key" aria-label="Permalink to &quot;Installs without OIDC: the API key&quot;">​</a></h2><p>Releases up to 1.4.0 ran with no login at all when <code>oidc.authority</code> was empty, the chart default: every request was the admin user <code>dev</code>. Later releases require a login, and the backend <strong>refuses to start</strong> without one.</p><p>A plain <code>helm upgrade</code> (with <code>-f</code>, <code>--reset-then-reuse-values</code> or <code>--reuse-values</code>) handles this for you. The chart generates an API key into the Secret <code>agenthub-api-key</code> and keeps it on every later upgrade. Because the release existed before the key, the key acts as <code>dev</code>, so your sessions, credentials and projects stay where they are. After the upgrade, read the key and enter it when the UI asks:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub-api-key</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jsonpath=&#39;{.data.api-key}&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> base64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span></span></code></pre></div><p>Scripts send it as <code>Authorization: Bearer &lt;key&gt;</code>. Personal API tokens and the remote MCP keep working; the MCP consent screen now asks for the key.</p><ul><li><strong>GitOps (<code>helm template</code>)</strong>: the chart cannot read the Secret back there, so a generated key would change on every render. Create a Secret with a key of at least 32 characters, then set <code>auth.apiKey.existingSecret=&lt;name&gt;</code> and, on an existing install, <code>auth.apiKey.owner=dev</code>.</li><li><strong>Rotating the key</strong>: write a new value into the Secret&#39;s <code>api-key</code> and run <code>kubectl -n agenthub rollout restart deployment/agenthub-backend</code>.</li><li><strong>Local development only</strong>: <code>auth.insecureDevMode=true</code> restores the old open mode, with a warning in the log and in the UI.</li></ul><p>Preview such an upgrade with <code>--dry-run=server</code>. With <code>--dry-run=client</code>, the chart cannot see the existing Secret and shows a key and owner it would not actually use.</p><h2 id="checking-what-an-upgrade-will-change" tabindex="-1">Checking what an upgrade will change <a class="header-anchor" href="#checking-what-an-upgrade-will-change" aria-label="Permalink to &quot;Checking what an upgrade will change&quot;">​</a></h2><p>A chart upgrade brings <em>every</em> change since the version you are on, not just the flag you came for. Render it first and look before you apply:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub/open-agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-values.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run=client</span></span></code></pre></div><p>New keys in the rendered ConfigMap are the quickest signal of how far the chart has moved.</p><h2 id="rollouts-and-single-replica-constraints" tabindex="-1">Rollouts and single-replica constraints <a class="header-anchor" href="#rollouts-and-single-replica-constraints" aria-label="Permalink to &quot;Rollouts and single-replica constraints&quot;">​</a></h2><p>The backend defaults to two replicas. Enabling Telegram or Signal forces it to one, because both integrations allow only a single consumer — see <a href="/docs/chat#one-replica-only">Chat integrations</a>. With one replica a rolling update briefly runs the old and new pod at the same time, so expect:</p><ul><li>A short window where the messenger poller logs a conflict. It resolves itself as soon as the old pod terminates.</li><li>No failover while the single pod restarts.</li></ul><p>Neither loses data: Telegram buffers updates by offset for about 24 hours.</p><h2 id="schema-changes-at-startup" tabindex="-1">Schema changes at startup <a class="header-anchor" href="#schema-changes-at-startup" aria-label="Permalink to &quot;Schema changes at startup&quot;">​</a></h2><p><strong>Community and Enterprise · operator.</strong> The backend creates and migrates its database schema itself, one replica at a time, before it answers <code>/healthz</code>. Since 1.21.3 (<a href="https://github.com/open-agenthub/open-agenthub/issues/538" target="_blank" rel="noreferrer">issue #538</a>), it remembers which schema changes it has already applied, in a table called <code>schema_scripts</code>:</p><ul><li><p><strong>A restart with an unchanged schema runs no schema changes.</strong> A replica no longer waits for long-running database transactions, and does not hold up the other replicas&#39; requests while it starts.</p></li><li><p><strong>The first start after an upgrade</strong> applies what changed. If another transaction holds a table it needs, the replica waits at most 2 seconds at a time, backs off so that live requests get through, and tries again. In our tests, requests to the running replicas waited at most about 2 seconds per attempt; this is not a total limit, since several attempts or other locks can hold requests up for longer. Each wait is logged with the transactions that were open:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Schema script PostgresSessionStore waited 2000 ms for a table lock and backed off (attempt 1);</span></span>
<span class="line"><span>retrying in 500 ms. Open transactions: pid 4711 (open-agenthub, idle in transaction, 42 s)</span></span></code></pre></div></li><li><p><strong>After 3 minutes</strong> of such waits for one store, or once the replica&#39;s 10-minute startup budget is used up (before the chart&#39;s startup probe would restart it), the replica stops with <code>Schema script … could not lock its tables</code> and the same list of transactions. See <a href="/docs/troubleshooting#schema-script-could-not-lock-its-tables">Troubleshooting</a>.</p></li></ul><p>The first start of this release on an existing database applies every store&#39;s schema once, because nothing has been recorded yet. Do not delete <code>schema_scripts</code>: without it, the next start applies everything again.</p><p>Releases before 1.21.3 ignore <code>schema_scripts</code>: if you go back to one, it runs its schema statements on every start as before, with its earlier waits. When you then return to 1.21.3, it finds its recorded changes unchanged and runs none. If you go back to a release that is itself 1.21.3 or newer and has different schema scripts, it applies its schema once on its first start, and the next upgrade once again, both with the bounded waits. This is not a general guarantee that older versions work with a newer schema.</p><h2 id="version-notes" tabindex="-1">Version notes <a class="header-anchor" href="#version-notes" aria-label="Permalink to &quot;Version notes&quot;">​</a></h2><p>What each release asks of an operator when upgrading to it. Releases not listed here need nothing beyond a normal <code>helm upgrade</code>. When you skip versions, apply the notes of every release in between.</p><p>Many releases ship new agent runtime images. A running session keeps its old image until it restarts: use <strong>Update now</strong> in the session header, or pause and resume the session. With <code>agent.autoUpdateRuntimeImages</code> on, idle interactive sessions are updated automatically.</p><h3 id="_1-0-0" tabindex="-1">1.0.0 <a class="header-anchor" href="#_1-0-0" aria-label="Permalink to &quot;1.0.0&quot;">​</a></h3><ul><li>From 0.13.x, new chart values arrive: helper containers (<code>sessionContainers.*</code>), model endpoints (<code>agent.modelEndpoints</code>), automatic runtime image updates, session resource limits and floors, and video limits (<code>files.maxVideoBytes</code>). Review them in your values file.</li><li>Restart running sessions once so they start from the new runtime images.</li><li>Optional: remove what earlier session deletions left behind in object storage. As an admin, call <code>POST /api/admin/session-storage-cleanup/dry-run</code>, review the listed prefixes, then send the returned token to <code>POST /api/admin/session-storage-cleanup/apply</code> within 15 minutes.</li></ul><h3 id="_1-2-0" tabindex="-1">1.2.0 <a class="header-anchor" href="#_1-2-0" aria-label="Permalink to &quot;1.2.0&quot;">​</a></h3><ul><li>Restart running sessions to get the new runtime images and the <code>/tmp</code> setup with the sticky bit.</li><li>The integrated browser gets them the next time its pod is created (<code>browser_stop</code>, then <code>browser_start</code>).</li></ul><h3 id="_1-3-0-and-1-4-0" tabindex="-1">1.3.0 and 1.4.0 <a class="header-anchor" href="#_1-3-0-and-1-4-0" aria-label="Permalink to &quot;1.3.0 and 1.4.0&quot;">​</a></h3><p>Both releases fix provider login data in stored session archives and add an admin cleanup. Run the 1.4.0 cleanup; see <a href="#archive-cleanups-after-1-3-0-and-1-4-0">Archive cleanups after 1.3.0 and 1.4.0</a>.</p><h3 id="_1-5-0" tabindex="-1">1.5.0 <a class="header-anchor" href="#_1-5-0" aria-label="Permalink to &quot;1.5.0&quot;">​</a></h3><p><strong>Breaking for installs without OIDC:</strong> the backend requires an API key and refuses to start without one. See <a href="#installs-without-oidc-the-api-key">Installs without OIDC: the API key</a>. Installs with <code>oidc.authority</code> set are not affected.</p><h3 id="_1-6-0" tabindex="-1">1.6.0 <a class="header-anchor" href="#_1-6-0" aria-label="Permalink to &quot;1.6.0&quot;">​</a></h3><ul><li>New values <code>backend.forwardedHeaders.knownProxies</code> and <code>knownNetworks</code>. They default to loopback and the private ranges; narrow them to your ingress controller&#39;s source range.</li><li>New value <code>sharing.userSuggestionsEnabled</code> (Enterprise sharing), default <code>true</code>.</li></ul><h3 id="_1-7-0" tabindex="-1">1.7.0 <a class="header-anchor" href="#_1-7-0" aria-label="Permalink to &quot;1.7.0&quot;">​</a></h3><p>Restart running sessions to get the new runtime images and agent CLIs.</p><h3 id="_1-8-0" tabindex="-1">1.8.0 <a class="header-anchor" href="#_1-8-0" aria-label="Permalink to &quot;1.8.0&quot;">​</a></h3><ul><li>The backend gets a startup probe that allows about 10.5 minutes, so one replica can wait for another replica&#39;s schema migration.</li><li>Schema migrations run on the first start, one replica at a time. The first start also prunes orphaned rows and holds write locks on the share, MCP policy and Slack thread tables until it commits. Session and share writes can be delayed for that time, depending on table size.</li><li>Restart running sessions to get the new runtime images and CLIs.</li></ul><h3 id="_1-9-0" tabindex="-1">1.9.0 <a class="header-anchor" href="#_1-9-0" aria-label="Permalink to &quot;1.9.0&quot;">​</a></h3><ul><li>The backend shares one Postgres pool per replica. New values <code>backend.database.maxPoolSize</code> (20) and <code>backend.database.lockPoolSize</code> (10).</li><li>Check the connection budget before upgrading or scaling: up to 32 connections per replica, 64 for two replicas, 96 during a rolling update. See <a href="/docs/chart-values#the-connection-budget">Chart values</a>.</li><li><strong>If you set <code>Maximum Pool Size</code> in <code>externalDatabase.connectionString</code>, <code>maxPoolSize</code> now overrides it.</strong></li></ul><h3 id="_1-10-0-1-10-1-and-1-12-1" tabindex="-1">1.10.0, 1.10.1 and 1.12.1 <a class="header-anchor" href="#_1-10-0-1-10-1-and-1-12-1" aria-label="Permalink to &quot;1.10.0, 1.10.1 and 1.12.1&quot;">​</a></h3><p>Restart running sessions (for 1.10.1, Claude Code sessions) to get the updated runtime.</p><h3 id="_1-12-0" tabindex="-1">1.12.0 <a class="header-anchor" href="#_1-12-0" aria-label="Permalink to &quot;1.12.0&quot;">​</a></h3><p>The chart narrows the egress rule that lets session pods reach object storage. If your external object storage is reached <strong>by DNS name on a port other than 80 or 443</strong>, set <code>agent.storageEgress.cidrs</code> to its networks, or add the port to <code>agent.extraEgressPorts</code>, <strong>before upgrading</strong>. This matters most if you had the bundled storage enabled and reached external storage on port 3900 through the old rule. Without it, affected sessions cannot save or restore their state; stored objects remain. Watch for the warning in the <code>helm upgrade</code> output.</p><h3 id="_1-14-0" tabindex="-1">1.14.0 <a class="header-anchor" href="#_1-14-0" aria-label="Permalink to &quot;1.14.0&quot;">​</a></h3><ul><li>The bundled Postgres is initialised in an init container. Existing data directories (a non-empty <code>PG_VERSION</code>) are left alone. Back up as usual before upgrading.</li><li>New value <code>postgres.appArmorUnconfined</code> (default <code>false</code>), a last resort for hosts whose AppArmor profile denies Postgres its own signals. For production, use <code>externalDatabase.connectionString</code>.</li><li>Restart running sessions to get the updated runtime images.</li></ul><h3 id="_1-14-1" tabindex="-1">1.14.1 <a class="header-anchor" href="#_1-14-1" aria-label="Permalink to &quot;1.14.1&quot;">​</a></h3><p>Deploy the new backend and frontend. Running sessions need no runtime update.</p><h3 id="archive-cleanups-after-1-3-0-and-1-4-0" tabindex="-1">Archive cleanups after 1.3.0 and 1.4.0 <a class="header-anchor" href="#archive-cleanups-after-1-3-0-and-1-4-0" aria-label="Permalink to &quot;Archive cleanups after 1.3.0 and 1.4.0&quot;">​</a></h3><p>Releases up to 1.3.0 could store provider login data in session state archives in object storage: Claude Code&#39;s configuration backups (up to 1.2.0), the Claude login file (0.1.0 to 0.4.0), and temporary login copies of all five agents (0.13.0 to 1.3.0). 1.3.0 and 1.4.0 stop new archives from containing them. Already stored archives need an admin cleanup.</p><p>The 1.4.0 cleanup, <code>provider-logins</code>, covers everything the 1.3.0 <code>claude-backups</code> cleanup covers and more. Run it even if you already ran the 1.3.0 one; a repeat run is safe.</p><ol><li><p>Deploy 1.4.0 or later.</p></li><li><p>Pause interactive sessions and wait until their pods are gone. Pausing returns before the pod has exited.</p></li><li><p>Run the cleanup per owner. <code>OWNER</code> is the session owner exactly as stored, normally the username; <strong>Settings → Users &amp; seats</strong> lists it under <strong>Admins &amp; roles</strong>. Authenticate as an admin with an OIDC access token, or with the API key on an install without OIDC. Preview first:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://hub.example.com/api/admin/session-storage-cleanup/provider-logins</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ADMIN_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;owner&quot;:&quot;OWNER&quot;,&quot;apply&quot;:false}&#39;</span></span></code></pre></div><p>Then send the same request with <code>&quot;apply&quot;:true</code>. The result reports counts only: <code>scanned</code>, <code>missing</code>, <code>clean</code>, <code>rewritten</code>, <code>skipped</code>, <code>failed</code>. <code>skipped: 0</code> and <code>failed: 0</code> mean every archive was handled; otherwise repeat after the reported sessions have stopped.</p></li><li><p>Resume the sessions.</p></li><li><p>Scheduled sessions are skipped while their CronJob exists. Their archive is replaced only after a run on the new runtime has written it successfully; check that such a run completed.</p></li><li><p>Revoke provider logins at the provider if they may be affected: Claude logins used under 0.1.0 to 0.4.0, and logins installed, refreshed or replaced while sessions ran 0.13.0 to 1.3.0. Cleaning an archive or deleting a session does not revoke a login.</p></li><li><p>Rotate credentials you configured as literal MCP header or environment values for Claude sessions.</p></li></ol><p>The cleanup does not reach values running processes already loaded, copies a CLI made itself, or your storage&#39;s object-version history and backups. Assess those separately.</p><h2 id="shared-protection-keys-and-secret-recovery" tabindex="-1">Shared protection keys and secret recovery <a class="header-anchor" href="#shared-protection-keys-and-secret-recovery" aria-label="Permalink to &quot;Shared protection keys and secret recovery&quot;">​</a></h2><p><strong>Community and Enterprise · operator and affected secret owner.</strong> For the release containing <a href="https://github.com/open-agenthub/open-agenthub/issues/458" target="_blank" rel="noreferrer">issue #458</a>, the Helm chart supplies a stable wrapping Secret for a shared Postgres key ring. Use a values file so the new chart defaults arrive. For offline/declarative rendering, configure <a href="/docs/chart-values#shared-protection-keys"><code>dataProtection.existingSecret</code></a> before upgrading.</p><p><strong>Values encrypted before the update with keys that are already lost need to be entered again.</strong> The update cannot recover a lost key. Unreadable values are retained, and list pages remain available:</p><ul><li>In <strong>Library → MCP servers</strong>, a secret-unavailable hint tells the owner to edit the entry and re-enter the secret. Administrators repair organisation catalog entries. A configured secret remains marked as present until explicitly replaced or cleared.</li><li>In webhook settings, an affected trigger shows a recovery hint. Recreate it, then update the delivery URL and secret in the repository&#39;s webhook settings. An administrator can instead restore the original keys before you recreate anything.</li><li>Register affected session API sources again with their secrets. Restart sessions to get new gateway tokens, and repeat any pending storage-cleanup dry run.</li></ul><p>The backend logs the number of unreadable stored secrets and recovery instructions. Operations that need an unreadable secret fail clearly until repaired. Editing an MCP server without supplying a new secret preserves the existing encrypted value.</p><p>If old file keys are still available, retain/export them <strong>before replacing the old pods</strong>. The backend automatically attempts migration from the surviving default HOME key directory. For an exported ring, mount it read-only and configure <code>DataProtection__LegacyKeysDirectory</code> and <code>DataProtection__LegacyApplicationName</code> to the exact original application discriminator (the old content-root path, normally including its trailing directory separator). Successfully readable values are rewritten using the shared ring. Old transient tokens are reissued rather than migrated. When several old pods had separate rings, preserve each export and migrate with each original ring; a single export cannot recover another pod&#39;s lost keys.</p><p>Afterward, include both the database and wrapping Secret in your backup/restore procedure. Do not delete or regenerate the Secret when retaining the database. A wrong/missing wrapping identity stops backend startup rather than replacing the ring.</p>`,80)])])}const g=a(n,[["render",r]]);export{u as __pageData,g as default};
